package com.aoo.bcg.common.repair;import java.time.*;import java.util.Set;import org.junit.jupiter.api.Test;import static org.junit.jupiter.api.Assertions.*;
class TemporaryRepairCapabilityTest{@Test void bindsAndAutomaticallyExpiresEveryTemporaryEntry(){var service=new TemporaryRepairCapability();var now=Instant.EPOCH;var grant=new TemporaryRepairCapability.Grant("g1","tool","deploy","cert:abc",Set.of("club.repair"),now,now.plusSeconds(30));service.issue(grant,Duration.ofMinutes(1));service.authorize("g1","tool","deploy","cert:abc","club.repair",now.plusSeconds(1));assertThrows(SecurityException.class,()->service.authorize("g1","wrong","deploy","cert:abc","club.repair",now));assertEquals(1,service.revokeExpired(now.plusSeconds(31)));assertThrows(SecurityException.class,()->service.authorize("g1","tool","deploy","cert:abc","club.repair",now.plusSeconds(31)));assertThrows(SecurityException.class,()->service.issue(grant,Duration.ofMinutes(1)));}}
